package net.civeira.phylax.features.access.consentpurpose.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.consentpurpose.domain.ConsentPurpose;
import net.civeira.phylax.features.access.consentpurpose.domain.valueobject.RequiredVO;

@RequiredArgsConstructor
public class RequiredValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<RequiredVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Boolean> getRequired() {
    return value.map(RequiredVO::isRequired);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<RequiredVO> getRequiredValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public RequiredVO readRequired(final Optional<ConsentPurpose> original,
      final ConstraintFailList fails) {
    RequiredVO result = value.orElse(original.map(ConsentPurpose::getRequiredValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "required", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param required
   * @return
   */
  public T required(RequiredVO required) {
    this.value = Optional.of(required);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param required
   * @return
   */
  public T required(Optional<RequiredVO> required) {
    this.value = required;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param required
   * @return
   */
  public T required(Boolean required) {
    this.value = Optional.of(RequiredVO.from(required));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetRequired() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetRequiredIfMatches(final String field) {
    if ("required".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
